import { test as base, expect, APIRequestContext, request as playwrightRequest } from "@playwright/test";
import fs from "fs";
import path from "path";
import { pathToFileURL } from "url";

function resolveDinouCoreModuleUrl(fileName: string): string {
  const candidates = [
    path.resolve(process.cwd(), "dinou/core", fileName),
    path.resolve(process.cwd(), "node_modules/dinou/dinou/core", fileName),
    path.resolve(process.cwd(), "node_modules/dinou/core", fileName),
  ];
  const found = candidates.find((p) => fs.existsSync(p)) ?? candidates[0];
  return pathToFileURL(found).href;
}

const HYDRATION_ERROR_REGEX =
  /hydration failed|server-rendered HTML|expected server HTML|did not match|didn't match|Minified React error #(418|419|422|423|425)/i;

// Fixture global: cualquier test que use `page` (o abra páginas nuevas en el contexto)
// fallará automáticamente si React emite algún error o warning de hidratación.
const test = base.extend({
  page: async ({ page }, use) => {
    const hydrationErrors: string[] = [];
    const trackedPages = new Set<any>();

    const waitForHydrationIfApplicable = async (p: any) => {
      try {
        if (!p || p.isClosed()) return;
        const url = p.url();
        if (!url || !url.startsWith("http://localhost:")) return;

        const shouldWait = await p.evaluate(() => {
          if (!document?.body) return false;
          if (document.body.getAttribute("data-hydrated") === "true") return false;
          if (document.readyState === "loading") return false;
          return Boolean(
            document.querySelector('script[src*="/main"], script[src*="/runtime"]')
          );
        });

        if (shouldWait) {
          await p.waitForSelector('body[data-hydrated="true"]', {
            state: "attached",
            timeout: 3000,
          });
        }
      } catch {
        // Ignorar si el test bloqueó JS/red a propósito, cerró la página o navegó fuera
      }
    };

    const attachHydrationWatchers = (p: any) => {
      if (trackedPages.has(p)) return;
      trackedPages.add(p);

      p.on("console", (msg: any) => {
        if (msg.type() === "error" || msg.type() === "warning") {
          const text = msg.text();
          if (HYDRATION_ERROR_REGEX.test(text)) {
            hydrationErrors.push(`[console.${msg.type()}] ${text}`);
          }
        }
      });
      p.on("pageerror", (err: Error) => {
        if (HYDRATION_ERROR_REGEX.test(err.message)) {
          hydrationErrors.push(`[pageerror] ${err.message}`);
        }
      });

      const origGoto = p.goto.bind(p);
      p.goto = async (...args: any[]) => {
        await waitForHydrationIfApplicable(p);
        return origGoto(...args);
      };
    };

    attachHydrationWatchers(page);
    page.context().on("page", (newPage) => attachHydrationWatchers(newPage));

    await use(page);

    for (const p of trackedPages) {
      await waitForHydrationIfApplicable(p);
    }

    expect(hydrationErrors, "Expected zero React hydration errors during test").toEqual([]);
  },
});
// Detectamos si estamos en un entorno de "start" (Producción) o Cloudflare / Deno
const isCloudflare = (process.env.TEST_CMD || "").includes("cloudflare") || (process.env.TEST_CMD || "").includes("wrangler");
const isDeno = (process.env.TEST_CMD || "").includes("deno");
const isProd = (process.env.TEST_CMD || "npm run build:esbuild && npm run start:esbuild").includes("start") || isCloudflare || isDeno;
const isDev = (process.env.TEST_CMD || "").includes("dev") && !isProd;
const isWebpack = (process.env.TEST_CMD || "").includes("webpack");

// Función auxiliar que espera hasta que el servidor diga "isReady: true"
async function pollUntilReady(request: APIRequestContext, maxRetries = 800) {
  console.log(
    "⏳ Esperando a que el servidor termine la generación estática (SSG)...",
  );

  for (let i = 0; i < maxRetries; i++) {
    try {
      // Hacemos petición al endpoint de estado
      const response = await request.get(
        `http://localhost:${process.env.PORT || 3000}/__DINOU_STATUS_PLAYWRIGHT__`,
      );
      const json = await response.json();

      if (json.isReady === true) {
        console.log("✅ Servidor reporta: READY. Comenzando tests estáticos.");
        return;
      }
    } catch (e) {
      // Si falla la conexión, ignoramos y reintentamos
    }

    // Esperamos 1 segundo antes del siguiente intento
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }

  throw new Error(
    "❌ Timeout: El servidor no terminó la generación estática a tiempo.",
  );
}

// Helper para peticiones de concurrencia que absorbe micro-glitches transitorios de sockets del SO (ECONNRESET)
async function safeApiGet(
  apiCtx: APIRequestContext,
  url: string,
  options?: Parameters<APIRequestContext["get"]>[1],
  retries = 2
) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await apiCtx.get(url, options);
    } catch (err: any) {
      const isSocketGlitch =
        err?.message?.includes("ECONNRESET") ||
        err?.message?.includes("socket hang up") ||
        err?.code === "ECONNRESET";
      if (isSocketGlitch && attempt < retries) {
        await new Promise((resolve) => setTimeout(resolve, 100));
        continue;
      }
      throw err;
    }
  }
  throw new Error(`Failed to GET ${url}`);
}

