      await expect(page.locator("#syn-direct-dynamic-token")).not.toHaveText(directDynPreWild, { timeout: 25000 });
      await expect(page.locator("#syn-shell-slot-token")).not.toHaveText(shellSlot2, { timeout: 25000 });
