    test("19. [Stage 2 / Check #53] Axis Y <DinouCacheSlot> Error Resilience During refreshSlot & revalidateTag + Clean Recovery", async ({
      page,
    }) => {
      test.skip(!isProd, "<DinouCacheSlot> error resilience fallback requires production mode");
      const { hydrationErrors, routerWarnings, pageErrors } =
        attachStrictWatchers(page);

      await page.goto("/t-3d-cube/cs-error");
      await waitCubeReady(page);

      try {
        await page.evaluate(() =>
          (window as any).__CUBE_3D__.mutate({ csFragileShouldThrow: false })
        );

        const baseHost = Number(await page.locator("#cserr-host-seq").textContent());
        const baseFragile = Number(await page.locator("#cserr-fragile-seq").textContent());
        const baseHealthy = Number(await page.locator("#cserr-healthy-seq").textContent());
        const poison = Math.max(baseHost, baseFragile, baseHealthy) + 899;

        await page.click("#probe-inc-cserr-host");
        await expect(page.locator("#probe-count-cserr-host")).toHaveText("1");

        // 1. Live refreshSlot while slot throws -> falls back to last known good cached slot, zero crash
        await page.evaluate(
          (patch) => (window as any).__CUBE_3D__.mutate(patch),
          {
            csErrHostSeq: poison,
            csHealthySeq: poison,
            csFragileShouldThrow: true,
            csFragileSeq: baseFragile + 631,
          }
        );
        await page.evaluate(() =>
          (window as any).__CUBE_3D__.refreshSlot("cube-cs-fragile", true)
        );
        await page.waitForTimeout(450);

        await expect(page.locator("#cserr-fragile-seq")).toHaveText(String(baseFragile));
        await expect(page.locator("#cserr-healthy-seq")).toHaveText(String(baseHealthy));
        await expect(page.locator("#cserr-host-seq")).toHaveText(String(baseHost));
        await expect(page.locator("#probe-count-cserr-host")).toHaveText("1");

        // Hard reload confirms cached slot.json & page index.html were NOT corrupted
        const res1 = await page.reload();
        expect(res1?.status()).toBe(200);
        await waitCubeReady(page);
        await expect(page.locator("#cserr-fragile-seq")).toHaveText(String(baseFragile));
        await expect(page.locator("#cserr-healthy-seq")).toHaveText(String(baseHealthy));
        await expect(page.locator("#cserr-host-seq")).toHaveText(String(baseHost));

        // 2. revalidateTag while slot throws -> preserves last known good cache without crashing or corrupting sibling
        await page.evaluate(
          (patch) => (window as any).__CUBE_3D__.mutate(patch),
          {
            csErrHostSeq: poison,
            csHealthySeq: poison,
            csFragileShouldThrow: true,
            csFragileSeq: baseFragile + 632,
          }
        );
        await page.evaluate(() =>
          (window as any).__CUBE_3D__.revalTag("cube-cs-tag-fragile")
        );
        const res2 = await page.reload();
        expect(res2?.status()).toBe(200);
        await waitCubeReady(page);
        await expect(page.locator("#cserr-fragile-seq")).toHaveText(String(baseFragile));
        await expect(page.locator("#cserr-healthy-seq")).toHaveText(String(baseHealthy));
        await expect(page.locator("#cserr-host-seq")).toHaveText(String(baseHost));

        // 3. Recovery via live refreshSlot once error clears -> updates cleanly & persists across F5
        const recovered1 = baseFragile + 633;
        await page.evaluate(
          (patch) => (window as any).__CUBE_3D__.mutate(patch),
          {
            csErrHostSeq: poison,
            csHealthySeq: poison,
            csFragileShouldThrow: false,
            csFragileSeq: recovered1,
          }
        );
        await page.evaluate(() =>
          (window as any).__CUBE_3D__.refreshSlot("cube-cs-fragile", true)
        );
        await expect(page.locator("#cserr-fragile-seq")).toHaveText(String(recovered1), {
          timeout: 10000,
        });
        await page.waitForTimeout(350);
        await page.reload();
        await waitCubeReady(page);
        await expect(page.locator("#cserr-fragile-seq")).toHaveText(String(recovered1));
        await expect(page.locator("#cserr-healthy-seq")).toHaveText(String(baseHealthy));
        await expect(page.locator("#cserr-host-seq")).toHaveText(String(baseHost));

        // 4. Recovery via revalidateTag -> updates cleanly while host & healthy sibling remain frozen
        const recovered2 = recovered1 + 1;
        await page.evaluate(
          (patch) => (window as any).__CUBE_3D__.mutate(patch),
          {
            csErrHostSeq: poison,
            csHealthySeq: poison,
            csFragileShouldThrow: false,
            csFragileSeq: recovered2,
          }
        );
        await page.evaluate(() =>
          (window as any).__CUBE_3D__.revalTag("cube-cs-tag-fragile")
        );
        await page.reload();
        await waitCubeReady(page);
        await expect(page.locator("#cserr-fragile-seq")).toHaveText(String(recovered2));
        await expect(page.locator("#cserr-healthy-seq")).toHaveText(String(baseHealthy));
        await expect(page.locator("#cserr-host-seq")).toHaveText(String(baseHost));

        expect(hydrationErrors).toEqual([]);
        expect(routerWarnings).toEqual([]);
        expect(pageErrors).toEqual([]);
      } finally {
        await page
          .evaluate(() =>
            (window as any).__CUBE_3D__?.mutate?.({ csFragileShouldThrow: false })
          )
          .catch(() => {});
      }
    });

    test("20. [Stage 3 / Check #54] Axis Z High-Concurrency 12-Way Stampede During 1s PPR Shell TTL Expiration (Causal Snapshot & Dedup)", async ({
      page,
      request,
    }) => {
      test.skip(!isProd, "1s PPR shell TTL stampede requires production mode");
      const { hydrationErrors, routerWarnings, pageErrors } =
        attachStrictWatchers(page);

      // Warm page and settle any prior TTL regeneration
      await page.goto("/t-3d-cube/ppr-stampede");
      await waitCubeReady(page);
      await page.waitForTimeout(450);
      await page.reload();
      await waitCubeReady(page);

      const baseShell = Number(
        await page.locator("#ppr-stampede-shell-seq").textContent()
      );
      const baseHole = Number(
        await page.locator("#ppr-stampede-hole-seq").textContent()
      );
      const nextShell = baseShell + 741;
      const nextHole = baseHole + 742;

      await page.evaluate(() => (window as any).__CUBE_3D__.resetStampedeExecs());
      await page.evaluate(
        (patch) => (window as any).__CUBE_3D__.mutate(patch),
        {
          pprStampedeShellSeq: nextShell,
          pprStampedeHoleSeq: nextHole,
        }
      );

      // Wait past the 1s PPR shell TTL
      await page.waitForTimeout(1300);

      // Fire 12 simultaneous HTTP requests + real browser reload right on TTL expiration
      const [httpBodies] = await Promise.all([
        Promise.all(
          Array.from({ length: 12 }, async () => {
            const res = await safeApiGet(request, "/t-3d-cube/ppr-stampede", {
              headers: { connection: "close" },
            });
            expect(res.status()).toBe(200);
            return await res.text();
          })
        ),
        (async () => {
          await page.reload();
          await waitCubeReady(page);
        })(),
      ]);

      // Verify causal snapshot consistency on EVERY SINGLE ONE of the 12 concurrent HTML streams!
      const baseShellStr = String(baseShell);
      const nextShellStr = String(nextShell);
      const nextHoleStr = String(nextHole);

      for (let i = 0; i < httpBodies.length; i++) {
        const html = httpBodies[i];
        const ssrMatch = html.match(/id="ppr-stampede-shell-seq"[^>]*>(\d+)</);
        expect(ssrMatch, `Response #${i} missing SSR shell seq`).toBeTruthy();
        const ssrVal = ssrMatch![1];
        expect(
          [baseShellStr, nextShellStr],
          `Response #${i} unexpected SSR shell val ${ssrVal}`
        ).toContain(ssrVal);

        // Streamed dynamic hole must always carry live nextHole
        expect(
          html.includes(`id="ppr-stampede-hole-seq">${nextHoleStr}<`),
          `Response #${i} missing live hole ${nextHoleStr}`
        ).toBe(true);

        // Extract inline page RSC script payloads (__DINOU_RSC_P__.push(...))
        const rscPushes = [...html.matchAll(/__DINOU_RSC_P__\|\|\[\]\)\.push\((.+?)\);/g)].map(
          (m) => m[1]
        );
        expect(
          rscPushes.length,
          `Response #${i} missing inline __DINOU_RSC_P__ payload`
        ).toBeGreaterThan(0);
        const joinedRsc = rscPushes.join("\n");

        // Causal invariant: SSR DOM shell value MUST match inline Flight payload (never mixed!)
        if (ssrVal === baseShellStr) {
          expect(
            joinedRsc.includes(baseShellStr) && !joinedRsc.includes(nextShellStr),
            `Response #${i} causal mismatch: SSR=${baseShellStr} paired with raced Flight=${nextShellStr}`
          ).toBe(true);
        } else {
          expect(
            joinedRsc.includes(nextShellStr) && !joinedRsc.includes(baseShellStr),
            `Response #${i} causal mismatch: SSR=${nextShellStr} paired with stale Flight=${baseShellStr}`
          ).toBe(true);
        }
      }

      // Wait for background SWR regeneration to settle, then verify deduplication (<= 1 shell regen!)
      await page.waitForTimeout(600);
      const shellExecs = await page.evaluate(() =>
        (window as any).__CUBE_3D__.getStampedeExecs()
      );
      expect(shellExecs).toBe(1);

      // Post-SWR reload serves fresh nextShell + live nextHole with 0 hydration errors
      await page.reload();
      await waitCubeReady(page);
      await expect(page.locator("#ppr-stampede-shell-seq")).toHaveText(nextShellStr);
      await expect(page.locator("#ppr-stampede-hole-seq")).toHaveText(nextHoleStr);

      expect(hydrationErrors).toEqual([]);
      expect(routerWarnings).toEqual([]);
      expect(pageErrors).toEqual([]);
    });

